// Find the main content area and scroll it
const mainContent = document.querySelector('.session-detail') || document.querySelector('main') || document.querySelector('.conversation-content');
if (mainContent) {
  mainContent.scrollTop = mainContent.scrollHeight / 2;
  'Scrolled main content';
} else {
  // Try scrolling the right panel
  const panels = document.querySelectorAll('[class*="panel"], [class*="content"], [class*="detail"]');
  panels.forEach(p => p.scrollTop = p.scrollTop + 500);
  'Scrolled panels: ' + panels.length;
}

// Find the conversation content area and scroll it down
const conversationArea = document.querySelector('.messages-container') || 
                          document.querySelector('.conversation-messages') ||
                          document.querySelector('[class*="message"]')?.parentElement;
if (conversationArea) {
  conversationArea.scrollTop += 800;
}
// Also try the main scrollable area
document.documentElement.scrollTop += 500;
'Scrolled';

// Scroll to the very bottom first
document.documentElement.scrollTop = document.documentElement.scrollHeight;
'Scrolled to bottom';

