   673→
   674→        // URL state management - use short project names in URLs
   675→        function getShortProjectName(fullName) {
   676→            const match = fullName.match(/-Desktop-(.+)$/);
   677→            return match ? match[1] : fullName.split('-').pop();
   678→        }
   679→
   680→        function getFullProjectName(shortName) {
   681→            // Find project by short name
   682→            const project = projects.find(p => getShortProjectName(p.name) === shortName);
   683→            return project ? project.name : shortName;
   684→        }
   685→
   686→        function updateUrl() {
